WITH flattened AS (SELECT id, service, host, log_ts, level, latency_ms, key, value FROM app_logs LATERAL VIEW EXPLODE(context) e AS key, value) SELECT CASE WHEN latency_ms >= 2126 THEN 'LARGE' ELSE 'SMALL' END AS latency_ms_tier, DATE_TRUNC('HOUR', log_ts) AS hour_window, BIT_OR(latency_ms) AS latency_ms_bit_or, COUNT(CASE WHEN service = 'search' THEN 1 END) AS search_count, ROUND(AVG(latency_ms), 2) AS avg_latency_ms, SORT_ARRAY(COLLECT_SET(host)) AS host_list, (UNIX_TIMESTAMP(MAX(log_ts)) - UNIX_TIMESTAMP(MIN(log_ts))) / 60 AS span_minutes, BIT_OR(latency_ms) AS latency_ms_bit_or_2 FROM flattened GROUP BY CASE WHEN latency_ms >= 2126 THEN 'LARGE' ELSE 'SMALL' END, DATE_TRUNC('HOUR', log_ts) HAVING search_count >= 1;
